from pathlib import Path
import json, re

prod = Path.home() / "prediction_research_prod"

def safe_json(path):
    try:
        if not path.is_file() or path.is_symlink():
            return None
        return json.loads(path.read_text())
    except Exception as e:
        return {"_parse_error": str(e)}

items = []
cand_dir = prod / "knowledge/candidates"
if cand_dir.is_dir():
    for p in sorted(cand_dir.glob("*.json")):
        d = safe_json(p)
        if not isinstance(d, dict) or not d.get("candidate_id"):
            continue
        items.append({
            "candidate_id": d.get("candidate_id"),
            "queue_status": d.get("queue_status"),
            "phase": d.get("phase"),
            "decision": d.get("decision"),
            "priority": d.get("priority"),
            "updated_at": d.get("updated_at"),
            "active_experiment_ids": d.get("active_experiment_ids") or [],
            "qualification_fixture": bool(d.get("qualification_fixture")),
            "next_decisive_test": d.get("next_decisive_test"),
            "protocols": d.get("prospective_protocols") or [],
        })

active_yaml = []
active_dir = prod / "candidates/active"
if active_dir.is_dir():
    for p in sorted(active_dir.iterdir()):
        if not p.is_file() or p.is_symlink():
            continue
        txt = p.read_text(errors="replace")
        def grab(key):
            m = re.search(r"(?m)^\s*" + re.escape(key) + r":\s*[\"']?([^\"'\n#]+)", txt)
            return m.group(1).strip() if m else None
        cid = grab("candidate_id") or grab("id")
        active_yaml.append({
            "file": p.name,
            "candidate_id": cid,
            "status": grab("status"),
            "economic_status": grab("economic_status"),
            "updated_at": grab("updated_at"),
        })

runtime_state = safe_json(prod / "knowledge/codex_runtime/STATE.json")
qual_state = safe_json(Path("/tmp/prediction-full-a2z-live-v4-state.json"))

status_counts = {}
for x in items:
    s = x.get("queue_status") or "UNSPECIFIED"
    status_counts[s] = status_counts.get(s, 0) + 1

build_inbox = [x for x in items if x.get("queue_status") in {
    "NEEDS_BUILD","ASTRA_PREBUILD_REVIEW","EXPERIMENT_REQUIRED","NEEDS_DIRECTOR"
}]
running = [x for x in items if x.get("queue_status") == "RUNNING" or x.get("active_experiment_ids")]
waiting = [x for x in items if x.get("queue_status") in {"WAITING_FOR_RESULT","PARKED"}]

summary = {
    "candidate_count": len(items),
    "status_counts": status_counts,
    "build_or_review_inbox": build_inbox,
    "running": running,
    "waiting_or_parked": waiting,
    "active_yaml": active_yaml,
    "supervisor_state": runtime_state,
    "qualification_v4": qual_state,
}
print("CANDIDATE_INVENTORY " + json.dumps(summary, separators=(",",":"), default=str), flush=True)
